{
  "queries": [
    {
      "doc_id": "SOP-P1-L3-01",
      "query": "For SOP-P1-L3-01 (Line startup - Machining line): list the required equipment checks and their acceptance criteria I must sign off on during first shift startup. Indicate which checks are the operator responsibility versus maintenance."
    },
    {
      "doc_id": "SOP-P2-L3-01",
      "query": "Compare SOP-P2-L3-01 (Line startup - Machining line) to SOP-P1-L3-01: what procedural or sign-off differences exist between the P2 and P1 versions that affect inspection points or allowed machine warm-up parameters?"
    },
    {
      "doc_id": "SOP-P1-L1-05",
      "query": "In SOP-P1-L1-05 (Planned shutdown - Hot Forge line) what are the required steps and minimum notification times for planned shutdowns? Identify any required calibration or preservation tasks for induction heaters before layup."
    },
    {
      "doc_id": "QS-PROC-03",
      "query": "From QS-PROC-03 (Ring rolling dimensional control (P1)): enumerate the dimensional characteristics that must be recorded on the first part and the control limits called out for ring ID, OD, and ring thickness. Also state sampling frequency for production runs."
    },
    {
      "doc_id": "ECN-2026-016",
      "query": "ECN-2026-016 (Change notice - Machining shot blast cabinet #1): summarize the equipment changes and list any new preventive maintenance or inspection requirements introduced by this ECN."
    },
    {
      "doc_id": "ECN-2026-045",
      "query": "For ECN-2026-045 (Change notice - Heat Treat heat treat furnace #2): describe the modification and whether there are new heat-treat cycle parameter limits or updated monitoring / data logging requirements that affect conforming part acceptance."
    },
    {
      "doc_id": "ECN-2026-019",
      "query": "ECN-2026-019 (Change notice - Ring Rolling shot blast cabinet #1): does this change require requalification of shot media, or update the shot flow/coverage acceptance criteria used in QS-PROC-03? If so, how?"
    },
    {
      "doc_id": "ECN-2026-015",
      "query": "For ECN-2026-015 (Change notice - Heat Treat heat treat furnace #3): identify any altered control limits or revised maintenance intervals that would impact thermal uniformity validation for production lots."
    },
    {
      "doc_id": "QS-CFW-1392-34",
      "query": "In QS-CFW-1392-34 (Quality specification - crankshaft blank CFW-1392-34 (4340)): list the dimensional tolerances and finish requirements called out for journal diameters, keyways, and critical runout. Also note any required NDT or hardness ranges."
    },
    {
      "doc_id": "SOP-P3-L1-04",
      "query": "SOP-P3-L1-04 (Shift handover - Hot Forge line): what handover items must be documented relating to furnace status, lot traceability, and in-process inspection results? Specify which fields are mandatory."
    },
    {
      "doc_id": "QS-CFW-7434-20",
      "query": "QS-CFW-7434-20 (Quality specification - connecting rod CFW-7434-20 (1045)): provide the specified dimensional tolerances for big-end and small-end bores and the acceptable surface finish for the rod beam. Indicate if straightness is controlled and how."
    },
    {
      "doc_id": "SOP-P1-L2-05",
      "query": "For SOP-P1-L2-05 (Planned shutdown - Ring Rolling line): detail the lockout/tagout and equipment preservation steps required, plus any ring rolling machine-specific pre-shutdown alignment or coolant drain procedures."
    },
    {
      "doc_id": "ECN-2026-030",
      "query": "ECN-2026-030 (Change notice - Machining hydraulic forging press #2): summarize mechanical or control changes and state whether press force/cycle monitoring criteria or verification intervals were revised."
    },
    {
      "doc_id": "ECN-2026-027",
      "query": "For ECN-2026-027 (Change notice - Hot Forge induction billet heater #3): identify modifications that affect soak time, temperature uniformity, or thermocouple locations; note any changed acceptance criteria for thermal profiling."
    },
    {
      "doc_id": "QS-CFW-3173-95",
      "query": "QS-CFW-3173-95 (Quality specification - gear blank CFW-3173-95 (8620)): list the tolerance band for blank OD and bore, runout or concentricity requirements, and any case depth or hardness range specified for subsequent heat treat."
    },
    {
      "doc_id": "ECN-2026-028",
      "query": "ECN-2026-028 (Change notice - Ring Rolling heat treat furnace #2): does this ECN change cycle profiles or instrumentation that would require requalification of heat treat recipes used for ring blanks? If yes, what revalidation steps are required?"
    },
    {
      "doc_id": "SOP-P2-L3-03",
      "query": "SOP-P2-L3-03 (First-article inspection - Machining line): what measurements and documentation are mandatory for first-article approval? Specify who is authorized to sign off and what constitutes a rejection."
    },
    {
      "doc_id": "QS-CFW-4540-42",
      "query": "QS-CFW-4540-42 (Quality specification - flange blank CFW-4540-42 (4140)): provide the dimensional tolerances for bolt circle diameter, flange thickness, and bore. Also state flatness/warpage criteria and any required surface hardness."
    },
    {
      "doc_id": "QS-CFW-1931-62",
      "query": "QS-CFW-1931-62 (Quality specification - gear blank CFW-1931-62 (8620)): what are the specified concentricity/runout limits between bore and OD, and are there differing inspection methods called out (CMM vs. comparator) for these checks?"
    },
    {
      "doc_id": "QS-CFW-5753-95",
      "query": "QS-CFW-5753-95 (Quality specification - track link CFW-5753-95 (15B37)): list critical dimensions and tolerances for pin bore and link width, and indicate any required hardness or plating acceptance criteria shown in the specification."
    }
  ]
